from lib import *
S = SS('w88')
steps = [
    step("SSE(Server-Sent Events)的响应就是一个普通的 HTTP 响应:Content-Type: text/event-stream,Cache-Control: no-cache,Transfer-Encoding: chunked(不设 Content-Length),连接保持打开,服务器不断追加文本。本机服务器先发 \"retry: 500\",再每 200 ms 发一个事件(id: 1、event: tick、data: message 1,一个空行结束)。每个数据块到达客户端的时刻是 0、205、410、616 ms,整个事件流文本 117 字节。发完 3 个事件后服务器直接掐断连接,没有发 chunked 结尾的 0 长度块,所以客户端看到的是“非正常结束”(正常结束 = False)。", t=tl(S(1)), mark=lidx(S(1), '响应头', '每个数据块到达的时刻'), done=lidx(S(1), '事件流文本', '连接在发完 3 个事件后'), b=bars([['第 1 块', 0, '0 ms'], ['第 2 块', 205, '205 ms'], ['第 3 块', 410, '410 ms'], ['第 4 块', 616, '616 ms']], 616, mark=[], done=[0, 1, 2, 3]), kv=KV([['Content-Type', 'text/event-stream'], ['传输', 'chunked,连接保持打开'], ['事件到达', '0 / 205 / 410 / 616 ms']], ['传输'])),
    step("事件流的文本格式:每行是 “字段名: 值”,空行表示一个事件结束。用我写的、按规范解析的解析器,服务器发出的这一串被解析成 4 个事件:两个 data 行变成一个事件、值用换行连接(“第一行\\n第二行”);event: update、id: 7、data: {\"x\":1} 是类型 update 的事件;“data:no-space”冒号后没有空格也行;“unknown: field”这个未知字段被忽略,同一事件里的 data 照常派发。以冒号开头的注释行 (“: 这是注释,用于保活”) 被忽略——常被用来定时发送以保持连接不被中间设备掐掉。最后一个“data: 没有结尾空行的事件”没有被派发:只有遇到空行事件才算结束。", t=tl(S(2)), mark=lidx(S(2), '派发的事件'), done=lidx(S(2), '服务器发出的原始文本', "': 这是注释"), kv=KV([['data 多行', '用换行连接成一个事件'], ['注释行', '冒号开头,忽略(保活)'], ['未知字段', '忽略'], ['没有结尾空行', '不派发']], ['没有结尾空行'])),
    step("断线重连与 Last-Event-ID。服务器每次发 3 个事件(id 递增)就断开,并在开头告诉客户端 retry: 500。我的客户端按规范实现:断线后等待 retry 毫秒,重新连接并带上 Last-Event-ID 请求头(最近收到的事件 id)。三轮收到的 id 是 [1, 2, 3]、[4, 5, 6]、[7, 8, 9]——没有重复、没有缺失;服务器记录到的三次请求带的 Last-Event-ID 依次是 None、3、6。从读到断线到下一次请求到达服务器的间隔 504 ms 和 502 ms(客户端睡了 500 ms,再加建立连接的时间)。注意:这个重连逻辑是我自己写的客户端实现的,浏览器的 EventSource 内置了同样的规则,我没有在浏览器里测。", t=tl(S(3)), mark=lidx(S(3), '三轮收到的事件 id', '服务器记录到的三次请求'), done=lidx(S(3), '断线(我们读到连接被掐断)'), kv=KV([['三轮 id', '[1,2,3] [4,5,6] [7,8,9]'], ['Last-Event-ID', '第一次无,之后 3、6'], ['重连间隔', '504 / 502 ms(retry: 500)']], ['Last-Event-ID'])),
    step("开销对比:推送 1000 条各 20 字节的消息,服务器→客户端方向的总字节。SSE:34110 字节(响应头 105 字节,每条事件文本 28 字节:\"data: \" 6 + 载荷 20 + \"\\n\\n\" 2,再加 chunked 框架 6 字节,共 34 字节);WebSocket:每条 2 字节帧头 + 20 字节载荷 = 22 字节,1000 条 22000 字节(不含一次性的升级握手);反复请求(同一条 keep-alive 连接上 1000 次 GET):85000 字节,每次响应头约 65 字节 + 20 字节载荷,另外客户端每次还要发 51 字节的请求,而且每条消息要多一个往返的延迟。所以按单条消息:WebSocket 22 字节 < SSE 34 字节 < 反复请求 85 字节。SSE 只能服务器→客户端单向;要双向就用 WebSocket。", t=tl(S(4)), mark=lidx(S(4), 'SSE:服务器发出', 'WebSocket:每条帧头', '反复请求'), done=lidx(S(4), '按单条消息'), b=bars([['WebSocket 每条', 22, '22 字节'], ['SSE 每条', 34, '34 字节'], ['反复请求 每条', 85, '85 字节']], 85, mark=[0, 1], done=[2]), kv=KV([['WebSocket', '22 字节 / 条'], ['SSE', '34 字节 / 条'], ['反复请求', '85 字节 / 条 + 客户端 51 字节 + 1 个往返']], ['SSE'])),
]
A = mkartw('w88', 88, '网络协议,HTTP,SSE,Server-Sent Events,EventSource,Last-Event-ID,真实验证,动画演示',
    '手工解析 SSE:chunked 的 text/event-stream 响应、事件陆续在 0 / 205 / 410 / 616 ms 到达;字段格式(多行 data、注释、未知字段、没有结尾空行不派发);断线重连带 Last-Event-ID,三轮 id 连续且无重复;推送 1000 条 20 字节消息 SSE 34 字节 / 条,WebSocket 22,反复请求 85。',
    'SSE 是 HTTP 里最简单的“服务器推送”:一个不结束的响应,一行行文本。它没有 WebSocket 的双向和二进制,但自带断线重连。这篇用本机服务器逐个验证它的格式、重连规则,以及和 WebSocket、反复请求相比每条消息的开销。',
    [('Last-Event-ID', '断线重连时客户端带上的请求头;三轮收到的 id 是 [1,2,3] [4,5,6] [7,8,9],无重复无缺失'), ('34 / 22 / 85 字节', '推送 20 字节消息时 SSE / WebSocket / 反复请求 每条的服务器→客户端开销'), ('504 ms', '客户端按 retry: 500 重连时,断线到下一次请求到达服务器的间隔')],
    [('流式响应', '<p>一个不设 Content-Length 的 chunked 响应,Content-Type: text/event-stream,服务器想发就发。</p>'),
     ('文本格式', '<p>字段名: 值,空行结束一个事件;多行 data 用换行连接;注释行用于保活;没有结尾空行的事件不会派发。</p>'),
     ('重连', '<p>服务器用 retry 指定重连等待时间,客户端用 Last-Event-ID 请求头告知断点,实现不丢不重。</p>'),
     ('开销', '<p>每条 20 字节消息:WebSocket 22 字节,SSE 34 字节,反复请求 85 字节(还多一个往返)。</p>')],
    steps,
    [ENV_W + '。全部在本机,服务器是我写的线程 + 套接字小程序;重连逻辑是我自己写的客户端实现的,不是浏览器的 EventSource;第四节的 SSE 与反复请求是实测字节数,WebSocket 是按帧格式算出来的(2 字节帧头 + 载荷)',
     '没有验证:浏览器 EventSource 的真实行为;HTTP/1.1 下浏览器对同一主机的 6 个连接上限对 SSE 的影响;HTTP/2 上 SSE 的多路复用;代理或负载均衡对长连接的缓冲和空闲超时;事件流的字符编码(只用 UTF-8);服务器发送 retry 之外的退避策略'],
    'SSE')
